def _template_synthetic_dataset(config: dict, seed: int = 42):
    """R4 synthetic stand-in (only used when allow_synthetic_data=True).
    input (3, 64, 64) (float); target kind 'binary'.
    Evidence: explicit:FakeData=(3, 64, 64); catalogue:CIFAR10=(3, 32, 32),10; model:first-Conv2d.in_channels=3"""
    input_shape = tuple(config.get("synthetic_input_shape", (3, 64, 64)))
    n = int(config.get("synthetic_num_samples", 256))
    g = torch.Generator().manual_seed(seed)
    x = torch.randn((n, *input_shape), generator=g)
    y = torch.randint(0, 2, (n,), generator=g).float()
    return torch.utils.data.TensorDataset(x, y)

def train_step(model: nn.Module, batch, optimizer, config: dict) -> torch.Tensor:
    """R3: forward + loss extracted from the training loop at line 223 (module level). The FL runtime performs
    zero_grad/backward/step; this function must only return the loss tensor."""
    device = next(model.parameters()).device
    batch = _template_to_device(batch, device)
    data = batch
    i = 0
    real_label = 1
    criterion = nn.BCELoss()
    nz = 100
    fake_label = 0
    real_cpu = data[0].to(device)
    batch_size = real_cpu.size(0)
    label = torch.full((batch_size,), real_label, dtype=real_cpu.dtype, device=device)
    output = model.netD(real_cpu)
    errD_real = criterion(output, label)
    noise = torch.randn(batch_size, nz, 1, 1, device=device)
    fake = model.netG(noise)
    label = torch.full_like(label, fake_label)
    output = model.netD(fake.detach())
    errD_fake = criterion(output, label)
    label = torch.full_like(label, real_label)
    output = model.netD(fake)
    errG = criterion(output, label)
    return errD_real + errD_fake + errG


def build_optimizer(model: nn.Module, config: dict):
    """Optimizer as declared in the source (informational: the FL runtime owns the optimizer)."""
    lr = config.get("learning_rate", None)
    try:
        opt = torch.optim.Adam(model.parameters(), lr=0.0002, betas=(0.5, 0.999))
    except Exception:
        opt = torch.optim.AdamW(model.parameters(), lr=lr or 1e-3)
    if lr is not None:
        for g in opt.param_groups:
            g["lr"] = lr
    return opt
